const CACHE='suomi-v309-16-verwaltung';
const FILES=['./','./index.html','./style.css?v=223','./fonts/dm-sans-latin-wght-normal.woff2','./fonts/dm-sans-latin-ext-wght-normal.woff2','./fonts/fraunces-latin-standard-normal.woff2','./fonts/fraunces-latin-ext-standard-normal.woff2','./impressum.html','./datenschutz.html','./unterstuetzen.html','./support.css?v=3','./support.mjs?v=11','./support-swarm.mjs?v=2','./app.js?v=178','./difficult-words.mjs?v=2','./dialogs.mjs?v=2','./dialogs.json','./translation-feedback.mjs?v=1','./word-lookup.mjs?v=2','./endings-practice.mjs?v=2','./lexicon.json','./learning-insights.mjs','./word-practice.mjs?v=61','./wordsearch.mjs','./wordsearch-ui.mjs?v=64','./auth.js?v=132','./avatars.mjs?v=2','./classrooms.js?v=105','./classrooms.css?v=88','./classroom-report.mjs?v=1','./quality-review.js?v=7','./site-extras.mjs?v=2','./duplicate-candidates.json','./supabase-config.js','./supabase-config.js?v=2','./review-plan.mjs?v=2','./learning-path.mjs?v=3','./learning-path-data.mjs','./grammar-topics.mjs','./verbs-data.mjs','./verb-examples.mjs?v=1','./verb-practice.mjs','./verbs.css?v=83','./sentences.json','./grammar.json','./icon.svg','./manifest.webmanifest','./games.mjs?v=11','./guest-card.mjs?v=13','./home-extras.mjs?v=14','./streak.mjs?v=6','./home-tabs.mjs?v=3','./daily-mix.mjs?v=3','./endings-progress.mjs?v=1','./guest-intro.mjs?v=29','./intro-birds.mjs?v=13','./intro-flock.mjs?v=1','./intro-flock-worker.mjs?v=1','./themes.mjs?v=6','./games.css?v=4','./grammar-book.css?v=1','./grammar-book.mjs?v=1','./grammar-book/fi-de/index.json?v=1','./grammar-book/fi-de/vokalharmonie.json?v=1','./grammar-book/fi-de/partitiv.json?v=1','./grammar-book/fi-de/stufenwechsel.json?v=1','./grammar-book/fi-de/ortsfaelle.json?v=1','./games-progress.mjs','./i18n.mjs?v=27','./locales/en.mjs?v=37'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('suomi-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
// Seitenaufrufe werden ohne Query-String und Anker gespeichert (?intro, ?x=1 …),
// sonst legt jede Variante einen eigenen Eintrag an und der Cache wächst unbegrenzt.
// Seiten selbst immer beim Server nachfragen (GitHub Pages erlaubt sonst 10 Minuten Browser-Cache):
// so ist nach dem Veröffentlichen beim nächsten Neuladen sofort die neue Fassung da.
const cacheKey=request=>{if(request.mode!=='navigate')return request;const u=new URL(request.url);return new Request(u.origin+u.pathname);};
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin)return;const key=cacheKey(event.request);event.respondWith(fetch(event.request.mode==='navigate'?new Request(event.request,{cache:'no-cache'}):event.request).then(response=>{if(response.ok&&response.type==='basic'&&!response.redirected){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(c=>c.put(key,copy)));}return response;}).catch(()=>caches.match(key).then(r=>r||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
